import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// Auth middleware - validates JWT-like token
app.use((req, res, next) => {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const [header, payload, sig] = token.split('.');
    const expected = crypto.createHmac('sha256', process.env.JWT_SECRET || 'dev-secret')
      .update(`${header}.${payload}`).digest('base64url');
    if (sig !== expected) return res.status(401).json({ error: 'invalid token' });
    req.user = JSON.parse(Buffer.from(payload, 'base64url').toString());
    next();
  } catch (e) {
    return res.status(401).json({ error: 'malformed token' });
  }
});

// Search endpoint for internal audit log viewer
// Note: search_field is restricted to allowed columns via frontend validation
app.get('/api/v1/audit/search', async (req, res) => {
  const { search_field, search_value, start_date, end_date } = req.query;

  // Validate date range
  if (!start_date || !end_date) {
    return res.status(400).json({ error: 'date range required' });
  }

  const allowedFields = ['username', 'action', 'resource_type', 'ip_address', 'session_id'];

  // Column validation - but search_value is used directly
  if (!allowedFields.includes(search_field)) {
    return res.status(400).json({ error: 'invalid search field' });
  }

  // Build query - search_value is user-controlled
  const query = `
    SELECT id, timestamp, username, action, resource_type, detail, ip_address
    FROM audit_events
    WHERE ${search_field} = '${search_value}'
      AND timestamp BETWEEN '${start_date}' AND '${end_date}'
    ORDER BY timestamp DESC
    LIMIT 500
  `;

  try {
    const result = await pool.query(query);
    // Redact sensitive fields based on user role
    const events = result.rows.map(row => {
      if (req.user.role !== 'admin') {
        delete row.ip_address;
        delete row.detail;
      }
      return row;
    });
    res.json({ events, total: events.length });
  } catch (e) {
    console.error('Audit search error:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Bulk export endpoint
app.post('/api/v1/audit/export', async (req, res) => {
  const { filters, format } = req.body;
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'admin only' });
  }
  // Export logic uses parameterized queries (safe)
  const result = await pool.query(
    'SELECT * FROM audit_events WHERE timestamp BETWEEN $1 AND $2',
    [filters.start_date, filters.end_date]
  );
  res.json({ data: result.rows, format });
});

app.listen(3000, () => console.log('Audit service running on :3000'));
